def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find complete rows (all same non-zero value)
    complete_rows = set()
    for r in range(rows):
        if cols > 0 and len(set(grid[r])) == 1 and grid[r][0] != 0:
            complete_rows.add(r)

    # Find complete columns (all same non-zero value)
    complete_cols = set()
    for c in range(cols):
        if rows > 0:
            col_vals = set(grid[r][c] for r in range(rows))
            if len(col_vals) == 1 and grid[0][c] != 0:
                complete_cols.add(c)

    # Build output grid
    output = [[0 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                # Background stays 0
                output[r][c] = 0
            elif r in complete_rows or c in complete_cols:
                # Complete structures transform to 2 (following demo pattern 6→2)
                output[r][c] = 2
            else:
                # Incomplete foreground stays as-is
                output[r][c] = val

    return output
